/* ==========================================================================
   Follow Up List — reads api/leads/getLeadFollowUps.php (leadFollowUps,
   generated by LeadFollowUpEngine::generateForLead() on lead creation).
   Actions reuse existing Lead Management endpoints:
   - Open Lead      -> /leads?leadId=... (auto-opens the existing Lead
                        Remarks modal there, see dist/assets/js/lead.js)
   - Mark Complete/
     Mark Skipped    -> api/leads/updateLeadFollowUpStatus.php
   - Add Note        -> api/leads/saveLeadRemark.php (existing endpoint,
                        nothing new added for notes)
   ========================================================================== */
$(function () {

    var getListUrl = API_BASE + '/leads/getLeadFollowUps.php';
    var updateStatusUrl = API_BASE + '/leads/updateLeadFollowUpStatus.php';
    var saveRemarkUrl = API_BASE + '/leads/saveLeadRemark.php';

    var rows = [];

    function esc(str) {
        return $('<div>').text(str == null ? '' : String(str)).html();
    }

    function notify(type, message) {
        if (typeof showToast === 'function') showToast(type, message);
    }

    function fmtDate(dateStr) {
        if (!dateStr) return '—';
        var d = new Date(dateStr + 'T00:00:00');
        if (isNaN(d.getTime())) return dateStr;
        return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    }

    function statusBadgeClass(status) {
        if (status === 'Completed') return 'btn-outline-success';
        if (status === 'Skipped') return 'btn-outline-secondary';
        return 'btn-outline-warning';
    }

    function currentFilters() {
        return {
            status: $('#flStatus').val(),
            dateFrom: $('#flDateFrom').val(),
            dateTo: $('#flDateTo').val(),
            search: $('#flSearch').val().trim()
        };
    }

    function loadList() {
        $('#followUpListTableBody').html(
            '<tr><td colspan="9" class="text-center text-muted py-3">Loading...</td></tr>'
        );

        $.getJSON(getListUrl, currentFilters(), function (response) {
            if (!response.success) {
                notify('danger', response.message || 'Unable to load follow ups.');
                rows = [];
                renderList();
                return;
            }
            rows = response.data || [];
            renderList();
        }).fail(function () {
            notify('danger', 'Unable to load follow ups.');
            rows = [];
            renderList();
        });
    }

    function renderList() {
        if (!rows.length) {
            $('#followUpListTableBody').html(
                '<tr><td colspan="9" class="text-center text-muted py-3">No follow ups match the current filters.</td></tr>'
            );
            return;
        }

        var html = '';
        rows.forEach(function (row) {
            var openLeadUrl = BASE_URL + '/leads?leadId=' + encodeURIComponent(row.leadId) +
                '&leadName=' + encodeURIComponent(row.leadName || '');

            var actions = '<a href="' + openLeadUrl + '" class="btn btn-sm btn-outline-primary" title="Open Lead">' +
                '<i class="ri-external-link-line"></i></a> ' +
                '<button type="button" class="btn btn-sm btn-outline-secondary add-note-btn" ' +
                    'data-lead-id="' + row.leadId + '" data-lead-name="' + esc(row.leadName) + '" title="Add Note">' +
                    '<i class="ri-sticky-note-line"></i></button>';

            if (row.status === 'Pending') {
                actions += ' <button type="button" class="btn btn-sm btn-outline-success mark-complete-btn" ' +
                        'data-id="' + row.id + '" title="Mark Complete">' +
                        '<i class="ri-check-line"></i></button>' +
                    ' <button type="button" class="btn btn-sm btn-outline-danger mark-skipped-btn" ' +
                        'data-id="' + row.id + '" title="Mark Skipped">' +
                        '<i class="ri-close-line"></i></button>';
            }

            html += '<tr>' +
                '<td>' + esc(row.leadName) + '</td>' +
                '<td>' + esc(row.phone) + '</td>' +
                '<td>' + esc(row.source) + '</td>' +
                '<td>' + esc(row.assignedToName) + '</td>' +
                '<td>' + fmtDate(row.dueDate) + '</td>' +
                '<td>' + row.followUpSequence + '</td>' +
                '<td>' + esc(row.followUpType) + '</td>' +
                '<td><span class="btn btn-sm ' + statusBadgeClass(row.status) + '">' + esc(row.status) + '</span></td>' +
                '<td>' + actions + '</td>' +
            '</tr>';
        });

        $('#followUpListTableBody').html(html);
    }

    function updateStatus(id, status) {
        $.ajax({
            url: updateStatusUrl,
            type: 'POST',
            contentType: 'application/json',
            dataType: 'json',
            data: JSON.stringify({ id: id, status: status })
        }).done(function (response) {
            if (response.success) {
                notify('success', response.message || 'Follow up updated.');
                loadList();
            } else {
                notify('danger', response.message || 'Failed to update follow up.');
            }
        }).fail(function () {
            notify('danger', 'Failed to update follow up.');
        });
    }

    $('#followUpListTableBody').on('click', '.mark-complete-btn', function () {
        if (!confirm('Mark this follow up as completed?')) return;
        updateStatus($(this).data('id'), 'Completed');
    });

    $('#followUpListTableBody').on('click', '.mark-skipped-btn', function () {
        if (!confirm('Skip this follow up?')) return;
        updateStatus($(this).data('id'), 'Skipped');
    });

    $('#followUpListTableBody').on('click', '.add-note-btn', function () {
        $('#fnLeadId').val($(this).data('lead-id'));
        $('#fnLeadName').text($(this).data('lead-name'));
        $('#fnRemark').val('');
        $('#followUpNoteModal').modal('show');
    });

    $('#saveFollowUpNoteBtn').on('click', function () {
        var remark = $('#fnRemark').val().trim();
        if (!remark) {
            notify('danger', 'Note is required.');
            return;
        }

        $.ajax({
            url: saveRemarkUrl,
            type: 'POST',
            dataType: 'json',
            data: {
                leadId: $('#fnLeadId').val(),
                remark: remark
            }
        }).done(function (response) {
            if (response.success) {
                notify('success', 'Note saved.');
                $('#followUpNoteModal').modal('hide');
            } else {
                notify('danger', response.message || 'Failed to save note.');
            }
        }).fail(function () {
            notify('danger', 'Failed to save note.');
        });
    });

    $('#flStatus, #flDateFrom, #flDateTo').on('change', loadList);

    var searchTimer = null;
    $('#flSearch').on('input', function () {
        clearTimeout(searchTimer);
        searchTimer = setTimeout(loadList, 300);
    });

    $('#flResetBtn').on('click', function () {
        $('#flStatus').val('Pending');
        $('#flDateFrom').val('');
        $('#flDateTo').val('');
        $('#flSearch').val('');
        loadList();
    });

    loadList();

});
